import { createLogger } from '@common/utils/logger';

const logger = createLogger('common.imageUrlToBase64');

/*
  NG- This is my temporary solution to dropdown menus with icons until the runtime supports
  image URLs in MenuItemTemplate. Currently showPopupMenu() templates work only with data URLs
  with Base64 encoding.
  This code needs to be removed and base64 icons should be replaced with direct image urls in popup menu
  templates once the runtime starts supporting them.
*/
export async function urlToBase64(url: string, width: number, height: number): Promise<string> {
    const img = document.createElement('img');
    img.crossOrigin = 'anonymous';

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = width;
    canvas.height = height;

    return await new Promise((resolve) => {
        img.onload = () => {
            if (!ctx) {
                logger.warn('urlToBase64', 'Could not get canvas context');
            }

            ctx?.drawImage(img, 0, 0, width, height);

            return resolve(canvas.toDataURL('image/png'));
        };
        img.onerror = () => {
            logger.warn('urlToBase64', 'Failed to load action image', { url });
            return resolve('');
        };
        img.src = url;
    });
}
