import { FC, useMemo } from 'react';

import styled from 'styled-components';

import { Icon } from '@openfin/ui-library';

import { dock3TestIds } from '@common/utils/test-ids';

import { BaseCustomDropdownItem } from '@common/api/action';

import { BaseCustomDropdown } from '@common/components/CustomDropdown/BaseCustomDropdown';

import { CompanionDockConfig, Dock3Config } from '@client-platform/shapes';

import { MoreMenuCustomOptionPayload } from '../api/protocol';
import { useActionsHandler } from '../hooks/useActionsHandler';
import { usePlatformIdentity } from '../hooks/usePlatformIdentity';

interface Props {
    alwaysOnTop: boolean;
    setAlwaysOnTop: (v: boolean) => void;
    companionDockConfig: Dock3Config | CompanionDockConfig;
    customMenuOptions?: BaseCustomDropdownItem[];
    customMenuLabel?: string;
    onCustomMenuClick?: (payload: MoreMenuCustomOptionPayload) => Promise<void>;
}

const MoreMenu: FC<Props> = ({
    alwaysOnTop,
    setAlwaysOnTop,
    companionDockConfig,
    customMenuOptions = [],
    customMenuLabel,
    onCustomMenuClick
}) => {
    const platformIdentity = usePlatformIdentity();
    const actionHandler = useActionsHandler(companionDockConfig, platformIdentity, alwaysOnTop, setAlwaysOnTop);

    const options = useMemo(() => {
        const baseOptions: BaseCustomDropdownItem[] = [
            { tooltip: 'Always On Top', action: 'alwaysOnTop', checked: alwaysOnTop },
            { separator: true },
            { tooltip: 'Minimize', action: 'minimize' },
            { separator: true }
        ];

        const hasCustomMenuOptions = customMenuOptions.length > 0;

        // Add custom menu if there are custom menu options
        if (hasCustomMenuOptions && customMenuLabel) {
            baseOptions.push({
                tooltip: customMenuLabel,
                options: customMenuOptions
            });
            baseOptions.push({ separator: true });
        }

        // Add quit option
        baseOptions.push({
            tooltip: companionDockConfig?.uiConfig?.moreMenu?.quitPlatform?.hidePlatformTitle
                ? 'Quit'
                : `Quit ${companionDockConfig?.title || 'Platform'}`,
            action: 'quit'
        });

        return baseOptions;
    }, [alwaysOnTop, companionDockConfig, customMenuOptions, customMenuLabel]);

    const handleMenuAction = async (action: string) => {
        // Handle built-in actions
        if (actionHandler[action]) {
            actionHandler[action]();
            return;
        }

        // Handle custom menu actions
        const isCustomMenuAction = customMenuOptions.some((option) => option.action === action);
        if (isCustomMenuAction && onCustomMenuClick) {
            await onCustomMenuClick({ action });
            return;
        }
    };

    return (
        <StyledDropdown
            data-testid={dock3TestIds.moreMenuDropdown}
            tooltip="More Options"
            onSelect={handleMenuAction}
            options={options}
            size="xlarge"
            rounded
        >
            <Icon icon="DotsVerticalIcon" size="xlarge" />
        </StyledDropdown>
    );
};

export default MoreMenu;

const StyledDropdown = styled(BaseCustomDropdown)`
    -webkit-app-region: no-drag;
    user-select: auto;

    height: ${({ theme }) => theme.px.xxxlarge};
    width: ${({ theme }) => theme.px.xxxlarge};

    &:hover {
        background-color: var(--color-shared-icon-button-default-background-hover);
    }

    &:active {
        background-color: var(--color-shared-icon-button-default-background-selected);
    }

    &[aria-expanded='true'] {
        background-color: var(--color-shared-icon-button-default-background-pressed);
    }
`;
