import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react';

import { BaseCustomDropdownItem } from '@common/api/action';
import { initWorkspaceIndicators } from '@common/utils/indicators/workspace-indicators';

import { DockEntry } from '@client-platform/shapes';

import { getDock3ChannelName } from '../api/constants';
import { Dock3ChannelClient, MoreMenuCustomOptionPayload } from '../api/protocol';
import { useCompanionDockConfiguration } from '../hooks/useCompanionDockConfiguration';
import { Dock3Config } from '../shapes';

const DockContext = createContext<Dock3ContextValue | null>(null);

type Dock3ContextValue = {
    config: Dock3Config;
    launchEntry: (entry: DockEntry, event: Pick<MouseEvent, 'ctrlKey' | 'metaKey' | 'shiftKey'>) => Promise<void>;
    setConfig: (config: Dock3Config) => void;
    bookmarkDockEntry: (entry: DockEntry) => Promise<void>;
    customMenuOptions?: BaseCustomDropdownItem[];
    customMenuLabel?: string;
    moreMenuCustomOptionClicked: (payload: MoreMenuCustomOptionPayload) => Promise<void>;
    clearContentMenuTargetId: () => void;
};

export const Dock3Provider = ({ children }: { children: React.ReactNode }) => {
    const initialConfig = useCompanionDockConfiguration<Dock3Config>();
    const [config, setConfig] = useState<Dock3Config>(initialConfig ?? {});
    const customMenuConfig = config?.uiConfig?.moreMenu?.moreMenuCustomOption;
    const customMenuOptions = customMenuConfig?.options || [];
    const customMenuLabel = customMenuConfig?.label;
    const clientRef = useRef<Dock3ChannelClient | null>(null);
    const navigationFrameRef = useRef<number | null>(null);
    const pendingTargetIdRef = useRef<string | null>(null);

    const saveConfig = useCallback((toSave: Dock3Config) => {
        if (clientRef.current) {
            clientRef.current.dispatch('save-config', { config: toSave }).catch((error) => {
                console.error(new Error('Failed to refresh Dock3 config:', { cause: error }));
            });
        }
    }, []);

    useEffect(() => {
        setConfig(initialConfig);
    }, [initialConfig]);

    useEffect(() => {
        (async () => {
            try {
                clientRef.current = (await fin.InterApplicationBus.Channel.connect(
                    getDock3ChannelName()
                )) as Dock3ChannelClient;

                clientRef.current.register('handle-dock-config-updated', async (newConfig: Dock3Config) => {
                    setConfig(newConfig);
                });

                clientRef.current.register('handle-indicator-config', async (config) => {
                    initWorkspaceIndicators(config);
                });

                clientRef.current.register('navigate-content-menu', async (payload: { targetId: string }) => {
                    // Update the pending targetId ref with the latest value
                    // This ensures rapid clicks always use the most recent targetId
                    pendingTargetIdRef.current = payload.targetId;

                    // Always clear first to ensure ContentMenu useEffect fires
                    setConfig((prevConfig) => {
                        const { contentMenuTargetId, ...rest } = prevConfig;
                        return rest;
                    });

                    // If there's already a pending frame, cancel it and create a new one
                    // This ensures every click gets processed, even rapid ones
                    if (navigationFrameRef.current !== null) {
                        cancelAnimationFrame(navigationFrameRef.current);
                        navigationFrameRef.current = null;
                    }

                    // Set the new targetId in the next animation frame
                    // Use a double frame to ensure the clear has been processed by React
                    navigationFrameRef.current = requestAnimationFrame(() => {
                        navigationFrameRef.current = requestAnimationFrame(() => {
                            const targetId = pendingTargetIdRef.current;
                            if (targetId) {
                                setConfig((currentConfig) => ({
                                    ...currentConfig,
                                    contentMenuTargetId: targetId
                                }));
                            }
                            navigationFrameRef.current = null;
                            pendingTargetIdRef.current = null;
                        });
                    });
                });

                clientRef.current.dispatch('ready', undefined).catch((error) => {
                    console.error(new Error('Failed to signal Dock3 ready state', { cause: error }));
                });
            } catch (error) {
                console.error(new Error('Failed to connect to Dock3 channel:', { cause: error }));
            }
        })();

        return () => {
            if (navigationFrameRef.current !== null) {
                cancelAnimationFrame(navigationFrameRef.current);
                navigationFrameRef.current = null;
            }
            if (clientRef.current) {
                clientRef.current.disconnect();
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Only run once on mount - handlers use functional setState to access latest config

    const bookmarkDockEntry = useCallback(async (entry: DockEntry) => {
        if (clientRef.current) {
            clientRef.current.dispatch('bookmark-content-menu-entry', { entry }).catch((error) => {
                console.error(new Error('Failed to bookmark dock entry:', { cause: error }));
            });
        }
    }, []);

    const launchEntry = useCallback(async (entry: DockEntry, sourceEvent: MouseEvent) => {
        if (!clientRef.current) {
            throw new Error('Dock3 channel client is not initialized.');
        }
        try {
            await clientRef.current.dispatch('launch-entry', { entry, sourceEvent });
        } catch (error) {
            console.error(new Error('Failed to launch dock entry:', { cause: error }));
            throw new Error('Failed to launch dock entry. Please try again later.');
        }
    }, []);

    const moreMenuCustomOptionClicked = useCallback(async (payload: MoreMenuCustomOptionPayload) => {
        if (clientRef.current) {
            try {
                await clientRef.current.dispatch('more-menu-custom-option-clicked', payload);
            } catch (error) {
                console.error('Failed to handle custom menu option click:', error);
            }
        }
    }, []);

    const setConfigInternal = useCallback(
        (newConfig: Dock3Config) => {
            setConfig(newConfig);
            saveConfig(newConfig);
        },
        [setConfig, saveConfig]
    );

    const clearContentMenuTargetId = useCallback(() => {
        setConfig((prevConfig) => {
            const { contentMenuTargetId, ...rest } = prevConfig;
            return rest;
        });
    }, []);

    return (
        <DockContext.Provider
            value={{
                config,
                launchEntry,
                setConfig: setConfigInternal,
                bookmarkDockEntry,
                customMenuOptions,
                customMenuLabel,
                moreMenuCustomOptionClicked,
                clearContentMenuTargetId
            }}
        >
            {children}
        </DockContext.Provider>
    );
};

export function useDock3Context(): Dock3ContextValue {
    const context = useContext(DockContext);
    if (!context) {
        throw new Error('useDock3 must be used within a Dock3Provider');
    }
    return context;
}
